wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use std::collections::BTreeSet;

use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        // `id` is a parser-computed digest, so it is safe to use as a store key.
        // Drop items already recorded in the 'seen' store, and also drop
        // repeats within this batch so each id passes at most once.
        let mut passed: BTreeSet<String> = BTreeSet::new();
        let mut out = Vec::with_capacity(items.len());
        for item in items {
            if passed.contains(&item.id) {
                continue;
            }
            if state_read::get(&item.id).is_some() {
                continue;
            }
            passed.insert(item.id.clone());
            out.push(item);
        }
        out
    }
}

export!(Node);
